 const fr=document.documentElement.lang==='fr',names=fr?{country:'pays',date:'date',title:'titre',location:'lieu',event:'code d’événement',reported_party:'parti',source_url:'lien source',campaign_id:'campagne',synthetic:'catégorie',notes:'notes'}:{country:'country',date:'date',title:'title',location:'location',event:'event code',reported_party:'party',source_url:'source link',campaign_id:'campaign',synthetic:'evidence category',notes:'notes'};
