 const lines=[s.payload.title,`${s.payload.location}, ${s.country} · ${s.payload.date}`,`Status: ${p.label}. ${p.note}`,`Visible resource value: ${v&&r.priced?money(v.low,v.high,v.currency):'not yet priced'} (${r.status==='reviewed'?'reviewed':'draft'}; ${r.priced} of ${r.total} resource groups priced)`];
